/**
 * Classify how a visitor reached the site, for the donate links.
 *
 * Pure functions with no DOM or storage access, so they can be unit tested.
 * The referrer lists are generated by bin/build-traffic-sources.js.
 */
// eslint-disable-next-line import/no-unresolved -- generated before build and test, not before lint.
import sources from './traffic-sources.json';

// The Foundation's own projects. Matomo's lists don't cover these.
const WIKIMEDIA = [
	'wikipedia.org',
	'wikimedia.org',
	'wiktionary.org',
	'wikidata.org',
	'mediawiki.org',
	'wikibooks.org',
	'wikiquote.org',
	'wikisource.org',
	'wikinews.org',
	'wikiversity.org',
	'wikivoyage.org',
	'wikimedia.de',
	'wikimedia.gr',
	'wikimedia.com',
	'wikimediastatus.net',
	'wikimediaendowment.org',
	'wikipedia25.org',
	'kiwix.org',
	'wikilovesmonuments.org',
	'wikimedia.zendesk.com',
	'wikimediapolicy.medium.com',
	'wikipedia25-years-of-wikipedia.toolforge.org',
];

const PAID_MEDIUM = /^(cpc|ppc|cpm|cpv|display|banner|paid.*)$/;
const EMAIL_MEDIUM = /^(e[-_]?mail|newsletter)$/;

const escapeRegExp = text => text.replace( /[.*+?^${}()|[\]\\]/g, '\\$&' );

/**
 * Build a function that tests "host/path" strings against host patterns.
 *
 * A pattern matches its host and any subdomain of it. `{}` stands for any
 * TLD or subdomain, as in Matomo's lists (`google.{}`).
 *
 * @param {string[]} patterns Host or host/path patterns.
 * @return {Function} Tests a lowercased "host/path" string.
 */
const buildMatcher = patterns => {
	const alternatives = patterns.map( pattern => pattern.split( '{}' ).map( escapeRegExp ).join( '[a-z0-9.-]+' ) );
	const regex = new RegExp( `^(?:[^/]*\\.)?(?:${ alternatives.join( '|' ) })(?:/|$)` );
	return subject => regex.test( subject );
};

const isAi = buildMatcher( sources.ai );

// Order matters: gemini.google.com is in both the AI and search lists, and
// www.facebook.com is in both the search and social lists.
const REFERRER_CATEGORIES = [
	[ 'wikimedia', buildMatcher( WIKIMEDIA ) ],
	[ 'ai', isAi ],
	[ 'social', buildMatcher( sources.social ) ],
	[ 'search', buildMatcher( sources.search ) ],
];

/**
 * Classify a page view by UTM parameters, then by referrer.
 *
 * @param {Object} visit          The page view.
 * @param {string} visit.referrer document.referrer, possibly empty.
 * @param {string} visit.search   location.search.
 * @param {string} visit.host     location.host.
 * @return {?string} wikimedia, ai, search, social, paid, email, referral or
 *                   direct. Null when the visitor came from another page of
 *                   this site, so the caller keeps its earlier answer.
 */
export const classifyVisit = ( { referrer, search, host } ) => {
	const params = new URLSearchParams( search );
	const medium = ( params.get( 'utm_medium' ) || '' ).toLowerCase();

	if ( PAID_MEDIUM.test( medium ) ) {
		return 'paid';
	}
	if ( EMAIL_MEDIUM.test( medium ) ) {
		return 'email';
	}
	// ChatGPT sends no referrer but adds utm_source=chatgpt.com.
	if ( isAi( ( params.get( 'utm_source' ) || '' ).toLowerCase() ) ) {
		return 'ai';
	}

	let url;
	try {
		url = new URL( referrer );
	} catch {
		return 'direct';
	}
	if ( url.host === host ) {
		return null;
	}

	const subject = ( url.hostname + url.pathname ).toLowerCase();
	const match = REFERRER_CATEGORIES.find( ( [ , matches ] ) => matches( subject ) );
	return match ? match[ 0 ] : 'referral';
};
